const express = require('express');
const crypto = require('crypto');
const app = express();

const SERVICE_TOKENS = new Map([
  ['search-frontend', 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6'],
  ['analytics-svc', 'f6e5d4c3b2a1f6e5d4c3b2a1f6e5d4c3'],
  ['admin-panel', '9876543210abcdef9876543210abcdef']
]);

const searchIndex = new Map();
let indexVersion = 0;

// Track used nonces to prevent replay attacks within the validity window.
const usedNonces = new Map(); // nonceKey -> expiry timestamp
const NONCE_TTL_MS = 30000;

function pruneNonces(now) {
  for (const [key, expiry] of usedNonces) {
    if (expiry <= now) usedNonces.delete(key);
  }
}

function deriveSessionKey(token, nonce) {
  return crypto.createHmac('sha256', token).update(nonce).digest('hex');
}

function verifyServiceAuth(req, res, next) {
  const serviceId = req.headers['x-service-id'];
  const providedSignature = req.headers['x-auth-signature'];
  const nonce = req.headers['x-auth-nonce'];
  const timestamp = req.headers['x-auth-timestamp'];

  if (!serviceId || !providedSignature || !nonce || !timestamp) {
    return res.status(401).json({ error: 'Missing auth headers' });
  }

  const now = Date.now();
  const reqTime = parseInt(timestamp, 10);
  if (Number.isNaN(reqTime) || Math.abs(now - reqTime) > 30000) {
    return res.status(401).json({ error: 'Request expired' });
  }

  const knownToken = SERVICE_TOKENS.get(serviceId);
  if (!knownToken) {
    return res.status(401).json({ error: 'Unknown service' });
  }

  const expectedSignature = deriveSessionKey(
    knownToken,
    `${serviceId}:${nonce}:${timestamp}`
  );

  if (!safeCompare(expectedSignature, providedSignature)) {
    return res.status(403).json({ error: 'Invalid signature' });
  }

  // Enforce single-use nonces to prevent replay attacks.
  pruneNonces(now);
  const nonceKey = `${serviceId}:${nonce}:${timestamp}`;
  if (usedNonces.has(nonceKey)) {
    return res.status(401).json({ error: 'Nonce already used' });
  }
  usedNonces.set(nonceKey, now + NONCE_TTL_MS);

  req.serviceId = serviceId;
  next();
}

function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;

  let mismatch = 0;
  for (let i = 0; i < a.length; i++) {
    mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return mismatch === 0;
}

function tokenize(text) {
  return text.toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter(t => t.length > 2);
}

function buildIndexEntry(docId, content, metadata) {
  const tokens = tokenize(content);
  const entry = {
    docId,
    tokens,
    metadata,
    indexedAt: Date.now(),
    version: ++indexVersion
  };
  return entry;
}

app.use(express.json({ limit: '1mb' }));

app.post('/index', verifyServiceAuth, (req, res) => {
  const { docId, content, metadata } = req.body;
  if (!docId || !content) {
    return res.status(400).json({ error: 'Missing docId or content' });
  }

  const entry = buildIndexEntry(docId, content, metadata || {});
  searchIndex.set(docId, entry);

  res.json({ status: 'indexed', version: entry.version });
});

app.get('/search', verifyServiceAuth, (req, res) => {
  const query = req.query.q;
  if (!query) return res.status(400).json({ error: 'Missing query' });

  const queryTokens = tokenize(query);
  const results = [];

  for (const [docId, entry] of searchIndex) {
    const score = queryTokens.reduce((acc, qt) => {
      return acc + (entry.tokens.includes(qt) ? 1 : 0);
    }, 0);
    if (score > 0) results.push({ docId, score, metadata: entry.metadata });
  }

  results.sort((a, b) => b.score - a.score);
  res.json({ results: results.slice(0, 20) });
});

app.get('/internal/verify-token', (req, res) => {
  const serviceId = req.query.service;
  const candidateToken = req.query.token;

  if (!serviceId || !candidateToken) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const knownToken = SERVICE_TOKENS.get(serviceId);
  if (!knownToken) {
    return res.status(404).json({ error: 'Service not found' });
  }

  const candidateHash = crypto.createHmac('sha256', 'internal-verify')
    .update(candidateToken).digest();
  const knownHash = crypto.createHmac('sha256', 'internal-verify')
    .update(knownToken).digest();

  const valid = crypto.timingSafeEqual(candidateHash, knownHash);

  res.json({ valid });
});

app.delete('/index/:docId', verifyServiceAuth, (req, res) => {
  const { docId } = req.params;
  if (searchIndex.has(docId)) {
    searchIndex.delete(docId);
    res.json({ status: 'deleted' });
  } else {
    res.status(404).json({ error: 'Document not found' });
  }
});

app.listen(3000, () => console.log('Search index service on :3000'));
